from fractions import Fraction
from typing import List, Union

INF = float("inf")

def order(coeffs: List[Union[int, Fraction]]) -> Union[int, float]:
    """Order (valuation) of a power series: index of first nonzero coefficient."""
    for i, c in enumerate(coeffs):
        if c != 0:
            return i
    return INF  # zero series (up to the available precision)

INF = float("inf")

def trop_add(a, b):
    """Tropical addition = min  (lower bounds the order of a sum)."""
    return min(a, b)

def trop_mul(a, b):
    """Tropical multiplication = ordinary addition  (order of a product)."""
    if a == INF or b == INF:
        return INF
    return a + b
